\midrule
MT$\times$score & 0.52 & \textbf{1.8e-5} & 0.52 & $\keff$ \\
MT$\times$syco & 0.28 & \textbf{0.012} & 0.49 & $\etamax$ \\
MT$\times$pos & 0.47 & \textbf{8.3e-5} & 0.44 & $\keff$ \\
MT$\times$verb & 0.18 & 0.108 & 0.47 & $\etamax$ \\
